<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\User\Domain\ValueObject\Accessor\UserWelcomeAtAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserWelcomeAtAccessor trait.
 *
 * Covers null default, string/VO assignment via withWelcomeAt,
 * getWelcomeAt/welcomeAt accessors, and isWelcomeAtChanged with/without original.
 */
class UserWelcomeAtAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withWelcomeAt creates a new instance with the WelcomeAt set
     * from a string value, and getWelcomeAt returns the primitive string.
     */
    public function testWithWelcomeAtFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserWelcomeAtAccessorUnitTest();

        // Act
        $result = $holder->withWelcomeAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $result->getWelcomeAt());
    }
    /**
     * Asserts that withwelcomeAt has access to the value object
     * from a string value, and getWelcomeAt returns the primitive string.
     */
    public function testWithWelcomeAtFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserWelcomeAtAccessorUnitTest();

        // Act
        $result = $holder->withWelcomeAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $result->welcomeAt()->value());
    }
    public function testChangedWelcomeAt(): void
    {
        // Arrange
        $holder = new ImplWithUserWelcomeAtAccessorUnitTest();
        $original = $holder->withWelcomeAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));
        $same = $holder->withWelcomeAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));
        $modified = $holder->withWelcomeAt((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')));

        // Act
        $unchanged = $holder->isWelcomeAtChanged();
        $withSame = $original->isWelcomeAtChanged($same);
        $withDiferent = $original->isWelcomeAtChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserWelcomeAtAccessorUnitTest
{
    use UserWelcomeAtAccessor;
}
